<?php include 'config.php'; $score=null; if($_SERVER['REQUEST_METHOD']=='POST'){ $user=trim($_POST['user_name']); $score=0; $total=0; $res=mysqli_query($conn,'SELECT * FROM questions'); while($r=mysqli_fetch_assoc($res)){ $total++; if(isset($_POST['q'.$r['id']]) && (int)$_POST['q'.$r['id']]==$r['correct_answer']) $score++; } $stmt=mysqli_prepare($conn,'INSERT INTO responses(user_name,score,total) VALUES(?,?,?)'); mysqli_stmt_bind_param($stmt,'sii',$user,$score,$total); mysqli_stmt_execute($stmt); }
$questions=mysqli_query($conn,'SELECT * FROM questions'); ?>
<!DOCTYPE html><html><head><title>Q19 Online Quiz</title><link rel="stylesheet" href="style.css"></head><body><div class="container"><h1>Online Quiz Application</h1><a href="admin.php">Admin: Add Questions</a><?php if($score!==null){ ?><h2>Your Score: <?php echo $score.' / '.$total; ?></h2><?php } ?><form method="post"><input name="user_name" placeholder="Your Name" required><?php while($r=mysqli_fetch_assoc($questions)){ ?><div class="card"><b><?php echo $r['question']; ?></b><label><input type="radio" name="q<?php echo $r['id']; ?>" value="1"> <?php echo $r['option1']; ?></label><br><label><input type="radio" name="q<?php echo $r['id']; ?>" value="2"> <?php echo $r['option2']; ?></label><br><label><input type="radio" name="q<?php echo $r['id']; ?>" value="3"> <?php echo $r['option3']; ?></label></div><?php } ?><button>Submit Quiz</button></form></div><script src="script.js"></script></body></html>
